// --- Mapa de areas ISA-95 por equipo -------------------------------------
const AREAS = { EQ01: 'CAPT', EQ02: 'FILT', EQ03: 'REAC' };
const EMPRESA = 'AQM';
const PLANTA = 'PTEF';

const d = msg.payload;
if (!d || d.value === undefined || !d.equipo) {
    node.warn('Payload invalido: ' + JSON.stringify(d));
    return null;
}

// Variable: del topic (AQM/PTEF/EQ01/CAUDAL) o del propio payload.
const partesTopic = String(msg.topic || '').split('/');
const variable = partesTopic[3] || (d.tag ? String(d.tag).split('-').pop() : 'NA');
const equipo = d.equipo;
const area = AREAS[equipo] || 'NA';
const tag = d.tag || [EMPRESA, PLANTA, area, equipo, variable].join('-');
const unit = d.unit || '';
const quality = (d.quality === undefined) ? 2 : parseInt(d.quality, 10);
const tsMs = d.ts || Date.now();

// --- Firma: hash corto (djb2) del payload original para trazabilidad -------
function djb2(str) {
    let h = 5381;
    for (let i = 0; i < str.length; i++) h = ((h << 5) + h + str.charCodeAt(i)) >>> 0;
    return h.toString(16).padStart(8, '0');
}
const firma = djb2(JSON.stringify(d));

// --- Escape de valores para tags ILP (coma, espacio, igual) ---------------
function esc(v) {
    return String(v).replace(/([,= ])/g, '\\$1');
}

// --- Construccion de la linea ILP ---------------------------------------
// measurement,tag_set field_set timestamp
const tagSet = [
    'planta=' + esc(PLANTA),
    'area=' + esc(area),
    'equipo=' + esc(equipo),
    'tag=' + esc(tag),
    'variable=' + esc(variable),
    'unit=' + esc(unit || 'NA'),
    'firma=' + esc(firma)
].join(',');

const fieldSet = 'value=' + Number(d.value) + ',quality=' + quality + 'i';
const linea = 'raw_variables,' + tagSet + ' ' + fieldSet + ' ' + tsMs;

msg.payload = linea;
msg.headers = {
    'Content-Type': 'text/plain; charset=utf-8'
};
const token = env.get('QUESTDB_TOKEN');
if (token) msg.headers['Authorization'] = 'Bearer ' + token;

msg.url = (env.get('QUESTDB_HTTP_URL') || 'http://localhost:9000') + '/write?precision=ms';
return msg;

// QuestDB responde 204 No Content cuando la insercion es correcta.
if (msg.statusCode && (msg.statusCode < 200 || msg.statusCode >= 300)) {
    node.error('QuestDB /write status ' + msg.statusCode + ': ' + msg.payload, msg);
    return [null, msg];
}
return [msg, null];

// Agregados de la ultima hora, una sola fila, formato largo -> condicional.
const sql = `SELECT
  avg(CASE WHEN equipo='EQ01' AND variable='CAUDAL' THEN value END) AS caudal_eq01,
  avg(CASE WHEN equipo='EQ01' AND variable='CORRIENTE' THEN value END) AS corriente_eq01,
  avg(CASE WHEN equipo='EQ01' AND variable='ESTADO' THEN value END) AS estado_eq01,
  avg(CASE WHEN equipo='EQ02' AND variable='TURB_IN' THEN value END) AS turbin_eq02,
  avg(CASE WHEN equipo='EQ02' AND variable='TURB_OUT' THEN value END) AS turbout_eq02,
  avg(CASE WHEN equipo='EQ02' AND variable='PRES_DIF' THEN value END) AS presdif_eq02,
  stddev(CASE WHEN equipo='EQ03' AND variable='PH' THEN value END) AS ph_sd_eq03,
  count(CASE WHEN equipo='EQ03' AND variable='PH' THEN 1 END) AS ph_n_eq03,
  count(CASE WHEN equipo='EQ03' AND variable='PH' AND (value < 6.5 OR value > 8.0) THEN 1 END) AS ph_fuera_eq03
FROM raw_variables
WHERE ts >= dateadd('h', -1, now()) AND quality = 2`;

msg.method = 'GET';
msg.url = (env.get('QUESTDB_HTTP_URL') || 'http://localhost:9000') + '/exec?query=' + encodeURIComponent(sql);
msg.headers = {};
const token = env.get('QUESTDB_TOKEN');
if (token) msg.headers['Authorization'] = 'Bearer ' + token;
return msg;

const r = msg.payload;
if (!r || !r.dataset || !r.dataset.length) {
    node.warn('Respuesta sin datos de QuestDB');
    return null;
}
const cols = r.columns.map(c => c.name);
const row = r.dataset[0];
const g = {};
cols.forEach((c, i) => { g[c] = row[i]; });

function num(v) { return (v === null || v === undefined) ? NaN : Number(v); }

const kpis = [];
function push(equipo, kpi_name, value, unit) {
    if (value === null || value === undefined || Number.isNaN(value)) return;
    kpis.push({ equipo, kpi_name, value: Number(value), period: 'hour', unit });
}

// --- EQ01 ---------------------------------------------------------------
const caudal = num(g.caudal_eq01), corriente = num(g.corriente_eq01);
if (corriente > 0) push('EQ01', 'eficiencia_energetica', +(caudal / corriente).toFixed(4), 'm3h_per_A');
push('EQ01', 'disponibilidad_bomba', +(num(g.estado_eq01) * 100).toFixed(2), '%');

// --- EQ02 ---------------------------------------------------------------
const tin = num(g.turbin_eq02), tout = num(g.turbout_eq02);
if (tin > 0) push('EQ02', 'eficiencia_filtracion', +(((tin - tout) / tin) * 100).toFixed(3), '%');
push('EQ02', 'presion_diferencial_media', +num(g.presdif_eq02).toFixed(2), 'mbar');

// --- EQ03 ---------------------------------------------------------------
const phn = num(g.ph_n_eq03), phf = num(g.ph_fuera_eq03);
if (phn > 0) push('EQ03', 'tiempo_fuera_rango_ph', +((60.0 * phf) / phn).toFixed(2), 'min');
push('EQ03', 'desviacion_ph', +num(g.ph_sd_eq03).toFixed(4), 'pH');

if (!kpis.length) { node.warn('No se pudo calcular ningun KPI'); return null; }

// --- Formatear como lineas ILP para kpi_values ------------------------
const tsMs = Date.now();
function esc(v) { return String(v).replace(/([,= ])/g, '\\$1'); }
const lineas = kpis.map(k =>
    'kpi_values,equipo=' + esc(k.equipo) +
    ',kpi_name=' + esc(k.kpi_name) +
    ',period=' + esc(k.period) +
    ',unit=' + esc(k.unit) +
    ' value=' + k.value + ' ' + tsMs
);

msg.payload = lineas.join('\n');
msg.method = 'POST';
msg.headers = { 'Content-Type': 'text/plain; charset=utf-8' };
const token = env.get('QUESTDB_TOKEN');
if (token) msg.headers['Authorization'] = 'Bearer ' + token;
msg.url = (env.get('QUESTDB_HTTP_URL') || 'http://localhost:9000') + '/write?precision=ms';
node.status({ text: kpis.length + ' KPIs @ ' + new Date(tsMs).toISOString() });
return msg;

// --- Umbrales por equipo/variable: [lo, hi] (null = ese lado no aplica) ---
const U = {
  EQ01: {
    CAUDAL:    { warning: [90, 155],  critical: [70, 175] },
    PRESION:   { warning: [3.5, 5.5], critical: [2.5, 6.5] },
    CORRIENTE: { warning: [null, 55], critical: [null, 65] },
    VIBRACION: { warning: [null, 4.5], critical: [null, 7.1] },
    ESTADO:    { critical: [0.5, null] }
  },
  EQ02: {
    TURB_IN:     { warning: [null, 15],  critical: [null, 25] },
    TURB_OUT:    { warning: [null, 1.5], critical: [null, 2.0] },
    PRES_DIF:    { warning: [null, 600], critical: [null, 800] },
    CAUDAL_FILT: { warning: [90, null],  critical: [70, null] },
    EFICIENCIA:  { warning: [80, null],  critical: [70, null] }
  },
  EQ03: {
    PH:      { warning: [6.5, 8.0], critical: [6.0, 8.5] },
    OD:      { warning: [1.5, 4.0], critical: [1.0, 5.0] },
    TEMP:    { warning: [15, 30],   critical: [10, 35] },
    CONDUCT: { warning: [null, 1800], critical: [null, 2200] },
    NIVEL:   { warning: [40, 90],   critical: [20, 95] }
  }
};

const d = msg.payload;
if (!d || d.value === undefined || !d.equipo) return null;

const partesTopic = String(msg.topic || '').split('/');
const variable = partesTopic[3] || 'NA';
const equipo = d.equipo;
const v = Number(d.value);
const reglas = (U[equipo] || {})[variable];
if (!reglas) return null;                 // variable sin umbrales definidos

function violado(rango) {
    if (!rango) return false;
    const [lo, hi] = rango;
    if (lo !== null && v < lo) return true;
    if (hi !== null && v > hi) return true;
    return false;
}

let severidad = null;
if (violado(reglas.critical)) severidad = 'critical';
else if (violado(reglas.warning)) severidad = 'warning';
if (!severidad) return null;               // dentro de rango: nada que hacer

const descripcion = equipo + '/' + variable + ' = ' + v + ' ' + (d.unit || '') +
    ' fuera de rango ' + severidad.toUpperCase() +
    ' [' + JSON.stringify(reglas[severidad]) + ']';

msg.severity = severidad;
msg.topic = '[' + severidad.toUpperCase() + '] AquaMonitor ' + equipo + '/' + variable;
msg.evento = {
    ts: d.ts || Date.now(),
    equipo: equipo,
    tag: d.tag || ['AQM','PTEF',equipo,variable].join('-'),
    event_type: 'THRESHOLD',
    description: descripcion,
    severity: severidad,
    value: v
};
msg.payload = descripcion;
return msg;

const e = msg.evento;
if (!e) return null;
function escTag(v) { return String(v).replace(/([,= ])/g, '\\$1'); }
function escStr(v) { return String(v).replace(/\\/g, '\\\\').replace(/"/g, '\\"'); }

const linea = 'events,equipo=' + escTag(e.equipo) +
    ',tag=' + escTag(e.tag) +
    ',event_type=' + escTag(e.event_type) +
    ',severity=' + escTag(e.severity) +
    ' description="' + escStr(e.description) + '",value=' + Number(e.value) +
    ' ' + e.ts;

msg.payload = linea;
msg.method = 'POST';
msg.headers = { 'Content-Type': 'text/plain; charset=utf-8' };
const token = env.get('QUESTDB_TOKEN');
if (token) msg.headers['Authorization'] = 'Bearer ' + token;
msg.url = (env.get('QUESTDB_HTTP_URL') || 'http://localhost:9000') + '/write?precision=ms';
return msg;

// Resumen del dia anterior en formato largo (section, clave, valor).
const sql = `SELECT 'kpi' AS section, concat(kpi_name, '|', equipo) AS clave, avg(value) AS valor
FROM kpi_values
WHERE period = 'day'
  AND ts >= dateadd('d', -1, date_trunc('day', now()))
  AND ts <  date_trunc('day', now())
GROUP BY kpi_name, equipo
UNION ALL
SELECT 'evento' AS section, severity AS clave, cast(count(*) AS double) AS valor
FROM events
WHERE ts >= dateadd('d', -1, date_trunc('day', now()))
  AND ts <  date_trunc('day', now())
GROUP BY severity
UNION ALL
SELECT 'anomalia' AS section, event_type AS clave, cast(count(*) AS double) AS valor
FROM events
WHERE event_type = 'ANOMALY_ZSCORE'
  AND ts >= dateadd('d', -1, date_trunc('day', now()))
  AND ts <  date_trunc('day', now())
GROUP BY event_type`;

msg.method = 'GET';
msg.url = (env.get('QUESTDB_HTTP_URL') || 'http://localhost:9000') + '/exec?query=' + encodeURIComponent(sql);
msg.headers = {};
const token = env.get('QUESTDB_TOKEN');
if (token) msg.headers['Authorization'] = 'Bearer ' + token;
return msg;

const r = msg.payload || {};
const cols = (r.columns || []).map(c => c.name);
const rows = (r.dataset || []).map(row => {
    const o = {};
    cols.forEach((c, i) => { o[c] = row[i]; });
    return o;
});

const kpis = [];
const eventos = { info: 0, warning: 0, critical: 0 };
let anomalias = 0;

rows.forEach(o => {
    if (o.section === 'kpi') {
        const [kpi_name, equipo] = String(o.clave).split('|');
        kpis.push({ equipo, kpi_name, valor: (o.valor === null ? 'N/D' : Number(o.valor).toFixed(3)) });
    } else if (o.section === 'evento') {
        eventos[o.clave] = Number(o.valor) || 0;
    } else if (o.section === 'anomalia') {
        anomalias = Number(o.valor) || 0;
    }
});

kpis.sort((a, b) => (a.equipo + a.kpi_name).localeCompare(b.equipo + b.kpi_name));

const ayer = new Date(Date.now() - 86400000).toISOString().slice(0, 10);
msg.reporte = {
    fecha: ayer,
    kpis: kpis,
    total_kpis: kpis.length,
    ev_info: eventos.info || 0,
    ev_warning: eventos.warning || 0,
    ev_critical: eventos.critical || 0,
    anomalias: anomalias,
    generado: new Date().toISOString()
};
msg.topic = 'Reporte diario AquaMonitor - ' + ayer;
return msg;
